 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    markers = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 5]
    if len(markers) < 2:
        return g

    # The marker surrounded by the colored pattern is its origin; the
    # remaining marker(s) indicate where to reproduce that pattern.
    def nearby_count(pos):
        r0, c0 = pos
        return sum(
            1 for r in range(max(0, r0 - 3), min(h, r0 + 4))
            for c in range(max(0, c0 - 3), min(w, c0 + 4))
            if (r, c) != pos and g[r][c] != 0
        )

    source = max(markers, key=nearby_count)
    sr, sc = source
    offsets = []
    for r in range(h):
        for c in range(w):
            if (r, c) != source and g[r][c] != 0:
                offsets.append((r - sr, c - sc, g[r][c]))

    for target in markers:
        if target == source:
            continue
        tr, tc = target
        g[tr][tc] = 0
        for dr, dc, color in offsets:
            rr, cc = tr + dr, tc + dc
            if 0 <= rr < h and 0 <= cc < w:
                g[rr][cc] = color
    return g
